const ESCAPE_REGEX_RE=/[-/\\^$*+?.()|[\]{}]/g;function escapeRegex(e){return e.replace(ESCAPE_REGEX_RE,`\\$&`)}function exactRegex(e,t){return RegExp(`^${escapeRegex(e)}$`,t)}function prefixRegex(e,t){return RegExp(`^${escapeRegex(e)}`,t)}function pathsRegex(e,t=process.platform){let n=e.map(e=>escapeRegex(e.replaceAll(`\\`,`/`)));return RegExp(`^(?:${n.join(`|`)})(?:[?#].*)?$`,t===`win32`?`i`:void 0)}export{escapeRegex,exactRegex,pathsRegex,prefixRegex};